            raise KeyError(f"Protocol version {protocol_version} is not supported")

def unit_of_work(metadata=None, timeout=None):
    @wraps(unit_of_work)
    def wrapper(function):
        @wraps(function)
        def wrapped(*args, **kwargs):
            tx = neo4j.transaction.Transaction(function.__name__, metadata, timeout)
            try:
                tx.begin()
                result = function(*args, **kwargs)
                tx.commit()
                return result
            except Exception as e:
                tx.rollback()
                raise e
        return wrapped
    return wrapper

