    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def mru_cache_decorator(func):
        cache = {}
        cache_order = []

        def wrapper(*args, **kwargs):
            if not typed:
                args_key = args
            else:
                args_key = tuple(args)
            if args_key not in cache:
                cache[args_key] = func(*args, **kwargs)
                cache_order.append(args_key)
                if len(cache_order) > maxsize:
                    cache.pop(cache_order.pop(0))
            return cache[args_key]

        return wrapper

    return mru_cache_decorator

