    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def _lfu_cache(func):
        cache = {}
        use_count = {}

        def wrapper(*args, **kwargs):
            if not typed:
                args = (args, kwargs)
            if args in cache:
                use_count[args] += 1
                return cache[args]
            else:
                result = func(*args, **kwargs)
                cache[args] = result
                use_count[args] = 1
                return result

        def clear():
            cache.clear()
            use_count.clear()

        wrapper.clear = clear
        return wrapper

