def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, str):
            if arg == "A" or arg == "B":
                new_args.append(arg)
        elif isinstance(arg, tuple):
            if arg[0] == "A" and arg[1] == "B":
                new_args.append(("A", "B"))
            elif arg[0] == "A" and arg[1] == "~B":
                new_args.append(("A", "B"))
            elif arg[0] == "B" and arg[1] == "A":
                new_args.append(("B", "A"))
            elif arg[0] == "B" and arg[1] == "~A":
                new_args.append(("B", "A"))
            elif arg[0] == "~A" and arg[1] == "A":
                new_args.append(("~A", "A"))
            elif arg[0] == "~A" and arg[1] == "B":
                new_args.append(("~A", "B"))
