            raise

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    least_freq_key = None
    least_freq_count = float('inf')
    for key, (value, count) in self.items():
        if count < least_freq_count:
            least_freq_key = key
            least_freq_count = count

    if least_freq_key is None:
        raise KeyError("popitem(): no key has a count of 0")

    value = self[least_freq_key]
    del self[least_freq_key]
    return (least_freq_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = self.pop()
    except IndexError:
        return None
    return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        key = random.choice(list(self))
        value = self[key]
        del self[key]
        return key, value
    except KeyError:
        raise KeyError("popitem(): mapping is empty") from None
    except (TypeError, IndexError):
        raise TypeError("popitem(): invalid input type") from None

def _create_in_regex(self) -> Pattern:
	"""
	Create the in-style parameter regular expression.

	Returns the in-style parameter regular expression (:class:`re.Pattern`).
	"""
	try:
		regex = r"^in\s*=\s*(?P<placeholder>\S+)"
		return re.compile(regex)
	except re.error:
		raise ValueError("Invalid regular expression") from None
	except Exception as e:
