def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        public_message = request.get_public_message()
        if public_message:
            return true
        private_message = request.get_private_message()
        if private_message:
            return true
        legacy_payload = request.get_legacy_payload()
        if legacy_payload:
            return true
        return false
    except:
        return false

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request.headers["User-Agent"] == "MatrixClient":
            return True
        else:
            return False
    except KeyError:
        return False

