def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise IRValidatorException("Mandatory data missing in spec file")
    try:
        spec_dict = yaml.load(spec_content, Loader=yaml.FullLoader)
    except yaml.YAMLError as e:
        raise IRValidatorException("Failed to load YAML data") from e
    if not spec_dict:
        raise IRValidatorException("Mandatory data missing in spec file")
    # validate required fields
    required_fields = ["title", "description", "version", "ports"]
    for field in required_fields:
        if field not in spec_dict:
            raise IRValidatorException(f"Mandatory field '{field}' missing in spec file")
    return spec_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    try:
        include_directive = parser_dict.get('include')
        if include_directive:
            included_files = include_directive.get('files')
            if included_files:
                for included_file in included_files:
                    with open(included_file, 'r') as file:
                        include_groups = yaml.safe_load(file)
                        parser_dict['groups'].append(include_groups)
                        for group in include_groups:
                            parser_dict['groups'].append(group['name'])
    except FileNotFoundError as e:
        raise ValueError(f"Include file `{included_file}` not found")
    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing include file `{included_file}`")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: a dict of resolved argument values keyed by argument name.
    """
    spec_defaults = {}
    for arg_name, arg_spec in self.spec['args'].items():
        if 'default' in arg_spec:
            spec_defaults[arg_name] = arg_spec['default']
    return spec_defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    # Step 1: Define the dictionary to store the deprecated options
    deprecated_args = {}

    # Step 2: Iterate through the command line arguments
    for arg in self.args:
        # Step 3: Check if the argument is deprecated
        if arg in self.deprecated_args:
            # Step 4: If the argument is deprecated, add it to the dictionary
            deprecated_args[arg] = self.deprecated_args[arg]

    # Step 5: Return the dictionary of deprecated options
    return deprecated_args

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        command_action = self.parsers[command_name].target_action
        if command_action is None:
            raise ValueError(f"Unknown command '{command_name}'")
        return command_action.option_specs
    except KeyError:
        raise ValueError(f"Unknown command '{command_name}'")

def get_silent_args(self, args):
    """
    Get a list of silenced argument names.

    :param args: A list of argument names.
    :return: A list of silenced argument names.
    """
    try:
        # Use a set to remove duplicates
        silent_args = set()
        for arg in args:
            # Check if the argument is a keyword argument
            if arg.startswith("--"):
                silent_args.add(arg.split("=")[0])
        return list(silent_args)
    except Exception as e:
        # If an exception occurs, return an empty list
        return []

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"The value of argument {arg} is longer than the specified length {self.length}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg[:2] == '--':
            arg += 2
            if arg not in ['min', 'max']:
                raise ValueError(f"Invalid argument: {arg}")
            else:
                validate_min_max_arg(self, arg)
        else:
            raise ValueError(f"Invalid argument: {arg}")

def get_nested_custom_and_control_args(args):
    """Split input arguments to control nested and custom.

    Args:
        args (list): the collected list of args.

    Returns:
        (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg.replace('--control-', '')] = args[arg]
        elif arg.startswith('--nested-'):
            nested_args[arg.replace('--nested-', '')] = args[arg]
        elif arg.startswith('--custom-'):
            custom_args[arg.replace('--custom-', '')] = args[arg]

    return (control_args, nested_args, custom_args)

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None:
        for var in extra_vars:
            vars_dict[var] = extra_vars.get(var, None)
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Step 1: Load the plugin spec file
    spec_file = os.path.join(plugin_dir, 'spec.json')
    with open(spec_file, 'r') as f:
        spec = json.load(f)

    # Step 2: Flatten the plugin spec dict
    flattened_dict = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flattened_dict[f'{key}.{subkey}'] = subvalue
        else:
            flattened_dict[key] = value

    return flattened_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get("CONFIG_PATH"):
        try:
            with open(os.path.join(os.path.dirname(__file__), "..", "config.ini")) as f:
                config_path = os.path.abspath(f.name)
            os.environ["CONFIG_PATH"] = config_path
        except OSError as e:
            print(f"Error: {e}")
            sys.exit(1)

def extend_cli(self, root_subparsers):
    # check if the root_subparsers parameter is valid
    if not isinstance(root_subparsers, argparse.ArgumentParser):
        raise TypeError("Invalid root_subparsers parameter: must be an argument parser object")
    # get the spec options from the sit_kwargs parameter
    spec_options = self.sit_kwargs.get('spec_options', {})
    # add the spec options to the root_subparsers object
    for option_name, option_kwargs in spec_options.items():
        if option_name not in root_subparsers.choices:
            raise TypeError(f"Invalid option name: {option_name}")
        root_subparsers.add_parser(option_name, **option_kwargs)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path must start with root!")
    return path[len(root):]
